-- OR across two filtered columns: one scan, no index fully usable
-- SELECT * FROM developers WHERE country = 'Japan' OR role = 'backend';

-- Split: each branch seeks its own index (real SQLite/PostgreSQL)
SELECT * FROM developers WHERE country = 'Japan'
UNION ALL
SELECT * FROM developers WHERE role = 'backend' AND country <> 'Japan';

